<?php
// Pure arithmetic / feed-contract tests. No WordPress, network or store writes.
define('ABSPATH',__DIR__);require __DIR__.'/../nilwears-bulk-manager/includes-price.php';require __DIR__.'/../nilwears-bulk-manager/includes-market.php';
$n=0;function market_check($ok,$label){global $n;$n++;if(!$ok)throw new Exception($label);}function market_bad($fn){try{$fn();return false;}catch(Throwable $e){return true;}}
$s=array('base_rate'=>250000,'allow_decrease'=>true,'rounding'=>'none','step'=>'10000','ending'=>'9000','decimals'=>0);
market_check(NIL_Market::price('495000',$s,275000)==='544500','10% from frozen base');market_check(NIL_Market::price('495000',$s,300000)==='594000','20% without compounding');market_check(NIL_Market::price('495000',$s,225000)==='445500','drop below base allowed');market_check(NIL_Market::price('',$s,275000)==='','blank sale not created');
$s['allow_decrease']=false;market_check(NIL_Market::price('495000',$s,225000)==='495000','below-base rate floored');$s['rounding']='down';market_check(NIL_Market::price('495000',$s,225000)==='499000','floor respected by rounding grid');market_check(NIL_Market::price('495000',$s,300000)==='589000','upside follows configured down-round');market_check(NIL_Market::price('495000',$s,275000)==='539000','decline above baseline is allowed');
foreach(array('up','down','nearest') as $mode){$s['rounding']=$mode;foreach(array(0.7,0.999,1,1.01,1.2,2) as $ratio){$price=NIL_Market::price('495000',$s,250000*$ratio);market_check((int)$price>=495000,'no-reduction floor');market_check((int)$price%10000===9000,'ending preserved');}}
$s['allow_decrease']=true;$s['rounding']='up';$s['decimals']=2;$s['step']='1';$s['ending']='0.99';market_check(NIL_Market::price('100.00',$s,275000)==='110.99','decimal rounding');$s['rounding']='none';market_check(NIL_Market::price('100.00',$s,275000)==='110.00','decimal ratio');market_check(market_bad(function()use($s){NIL_Market::price('100000000000',$s,500000);}), 'price overflow rejected');
$raw=array('price'=>2500000,'divide10'=>true,'unit'=>'تومان','updated_ms'=>time()*1000);$payload=array('indicators'=>array('price_dollar_rl'=>$raw));$out=NIL_Market::parse($payload);market_check($out['rates']['price_dollar_rl']['price']===250000.0,'rial feed divided once');market_check(isset($out['errors']['gold18k']),'missing asset isolated');$payload['indicators']['price_dollar_rl']['divide10']=false;market_check(NIL_Market::parse($payload)['rates']['price_dollar_rl']['price']===2500000.0,'already display-scaled rate not divided');
foreach(array(array('price',0),array('price',-1),array('price','bad'),array('divide10','true'),array('unit','USD'),array('updated_ms',(time()-3601)*1000),array('updated_ms',(time()+301)*1000)) as $bad){$p=array('indicators'=>array('price_dollar_rl'=>array_merge($raw,array($bad[0]=>$bad[1]))));market_check(market_bad(function()use($p){NIL_Market::parse($p);}), 'bad/stale feed rejected');}
market_check(market_bad(function(){NIL_Market::parse(array('error'=>'unavailable'));}),'malformed feed rejected');echo "PASS: $n market arithmetic/feed checks\n";
